(104, 'housing-alu', '알루미늄 하우징 Slate 75', 109000, 14, 'https://images.unsplash.com/photo-1541140532154-b024d705b909?auto=format&fit=crop&w=800&q=80', '실용적인 75% 콤팩트 배열의 아노다이징 알루미늄 Slate 하우징입니다.', TRUE, FALSE, NULL, 0, NOW(), NOW()),
(105, 'housing-alu', '알루미늄 하우징 Cobalt 75', 115000, 12, 'https://images.unsplash.com/photo-1550745165-9bc0b252726f?auto=format&fit=crop&w=800&q=80', '단단한 타건음과 묵직한 하판 무게추를 갖춘 75배열 Cobalt 하우징입니다.', TRUE, FALSE, NULL, 0, NOW(), NOW()),
(106, 'housing-alu', '알루미늄 하우징 Frame TKL', 129000, 25, 'https://images.unsplash.com/photo-1618384887929-16ec33fab9ef?auto=format&fit=crop&w=800&q=80', '표준 텐키리스(TKL) 레이아웃의 견고한 풀 알루미늄 Frame 하우징입니다.', TRUE, FALSE, NULL, 0, NOW(), NOW()),
(1, 'housing-alu', '에르고 87 CNC 풀 알루미늄 하우징 킷', 159000, 15, 'https://images.unsplash.com/photo-1587829741301-dc798b83add3?auto=format&fit=crop&w=800&q=80', '단단한 무게감과 묵직한 타건감을 제공하는 87배열 아노다이징 알루미늄 하우징입니다.', TRUE, FALSE, NULL, 0, NOW(), NOW()),
(2, 'housing-alu', 'Q1 Pro 75% 풀 알루미늄 가스켓 베어본', 189000, 8, 'https://images.unsplash.com/photo-1511467687858-23d96c32e4ae?auto=format&fit=crop&w=800&q=80', 'CNC 정밀 가공 바디와 실리콘 가스켓 마운트가 조화를 이룬 75배열 프리미엄 하우징입니다.', TRUE, FALSE, NULL, 0, NOW(), NOW()),
(4, 'housing-acrylic', '프로스트 65 아크릴 베어본', 72000, 10, 'https://images.unsplash.com/photo-1541140532154-b024d705b909?auto=format&fit=crop&w=800&q=80', '은은한 안개 질감의 반투명 무광 아크릴 65배열 하우징입니다.', TRUE, FALSE, NULL, 0, NOW(), NOW()),
(7, 'housing-plastic', '엔트리 87 레트로 사출 플라스틱 하우징', 35000, 25, 'https://images.unsplash.com/photo-1550745165-9bc0b252726f?auto=format&fit=crop&w=800&q=80', '가볍고 입문하기 좋은 표준 87키 ABS 사출 하우징입니다.', TRUE, FALSE, NULL, 0, NOW(), NOW()),
(8, 'housing-wood', '월넛 원목 클래식 65 하우징', 68000, 14, 'https://images.unsplash.com/photo-1626785774573-4b799315345d?auto=format&fit=crop&w=800&q=80', '천연 호두나무 원목을 깎아 만들어 따스한 울림과 우아함을 주는 65배열 목재 하우징입니다.', TRUE, FALSE, NULL, 0, NOW(), NOW()),
(14, 'housing-wood', '로즈우드 프리미엄 87 TKL 원목 하우징', 89000, 11, 'https://images.unsplash.com/photo-1618384887929-16ec33fab9ef?auto=format&fit=crop&w=800&q=80', '고급 장미목의 중후한 결착력과 깊은 타건음을 느낄 수 있는 87배열 목재 하우징입니다.', TRUE, FALSE, NULL, 0, NOW(), NOW()),
(26, 'pcb-hotswap', '87키 정방향 RGB 핫스왑 기판 (Type-C)', 45000, 22, 'https://images.unsplash.com/photo-1587829741301-dc798b83add3?auto=format&fit=crop&w=800&q=80', '스위치를 납땜 없이 손쉽게 교체할 수 있는 87키 카일 정품 핫스왑 소켓 기판입니다.', TRUE, FALSE, NULL, 0, NOW(), NOW()),
(27, 'pcb-hotswap', '75배열 플렉스컷 핫스왑 PCB', 49000, 15, 'https://images.unsplash.com/photo-1511467687858-23d96c32e4ae?auto=format&fit=crop&w=800&q=80', '75% 배열 전용 탄성 있는 부드러운 타건감을 구현한 플렉스컷 기판입니다.', TRUE, FALSE, NULL, 0, NOW(), NOW()),
(30, 'pcb-wireless', '87키 트라이모드 (유선/블루투스/2.4G) 무선 기판', 59000, 14, 'https://images.unsplash.com/photo-1618384887929-16ec33fab9ef?auto=format&fit=crop&w=800&q=80', '저지연 2.4GHz 무선과 블루투스 5.0을 동시 지원하는 87배열 무선 기판입니다.', TRUE, FALSE, NULL, 0, NOW(), NOW()),
(31, 'pcb-wireless', '65% 블루투스 5.1 듀얼 무선 PCB', 52000, 18, 'https://images.unsplash.com/photo-1601445638532-3c6f6c3aa1d6?auto=format&fit=crop&w=800&q=80', '스마트폰과 태블릿, PC까지 3대 멀티페어링이 가능한 65% 무선 기판입니다.', TRUE, FALSE, NULL, 0, NOW(), NOW()),
(32, 'pcb-wireless', '75% 트라이모드 가스켓 핫스왑 PCB', 55000, 20, 'https://images.unsplash.com/photo-1550745165-9bc0b252726f?auto=format&fit=crop&w=800&q=80', '75% 가스켓 마운트 빌드에 최적화된 저소음 고효율 무선 핫스왑 기판입니다.', TRUE, FALSE, NULL, 0, NOW(), NOW()),
(34, 'kb-65', 'KBD67 Lite 65% 커스텀 베어본 키트', 129000, 12, 'https://images.unsplash.com/photo-1595225476474-87563907a212?auto=format&fit=crop&w=800&q=80', '하우징, 기판, 보강판이 완벽 조화된 스테디셀러 65% 베어본 키트입니다.', TRUE, FALSE, NULL, 0, NOW(), NOW()),
(35, 'kb-75', 'MonsGeek M1W 75% 무선 풀알루 베어본', 139000, 16, 'https://images.unsplash.com/photo-1541140532154-b024d705b909?auto=format&fit=crop&w=800&q=80', '가스켓 구조와 노브 다이얼을 탑재한 올인원 75% 풀 알루미늄 베어본입니다.', TRUE, FALSE, NULL, 0, NOW(), NOW()),
(36, 'kb-tkl', 'Tiger 80 Lite 텐키리스 베어본 키트', 159000, 9, 'https://images.unsplash.com/photo-1618384887929-16ec33fab9ef?auto=format&fit=crop&w=800&q=80', '깊고 쫀득한 바닥 타건감을 자랑하는 리프스프링 마운트 87키 TKL 베어본입니다.', TRUE, FALSE, NULL, 0, NOW(), NOW()),
(37, 'kb-65', 'NEO 65 미니멀 알루미늄 무선 베어본', 119000, 14, 'https://images.unsplash.com/photo-1587829741301-dc798b83add3?auto=format&fit=crop&w=800&q=80', '볼 캐치 결합 방식으로 나사 없이 간편하게 분해 조립이 가능한 혁신적인 65% 베어본입니다.', TRUE, FALSE, NULL, 0, NOW(), NOW()),
(17, 'switch-linear', '바나나 스플릿 리니어 스위치 45g (90개입)', 45000, 40, 'https://images.unsplash.com/photo-1595225476474-87563907a212?auto=format&fit=crop&w=800&q=80', '서걱임 없는 매끄러운 슬라이딩과 바닥을 치는 깔끔한 로우피치 리니어 스위치입니다.', TRUE, FALSE, NULL, 0, NOW(), NOW()),
(20, 'switch-tactile', '홀리판다 V2 택타일 스위치 67g (90개입)', 65000, 20, 'https://images.unsplash.com/photo-1541140532154-b024d705b909?auto=format&fit=crop&w=800&q=80', '시작부터 강하게 걸리는 압도적인 구분감과 경쾌한 바닥음을 자랑하는 택타일 축입니다.', TRUE, FALSE, NULL, 0, NOW(), NOW()),
(21, 'switch-silent', '저소음 바다소금 넌클릭 택타일 (90개입)', 39000, 25, 'https://images.unsplash.com/photo-1618384887929-16ec33fab9ef?auto=format&fit=crop&w=800&q=80', '사무실에서도 사용할 수 있는 정숙한 소음 억제 설계의 저소음 스위치입니다.', TRUE, FALSE, NULL, 0, NOW(), NOW()),
(23, 'switch-click', '카일 박스 화이트 클릭 스위치 50g (90개입)', 42000, 16, 'https://images.unsplash.com/photo-1601445638532-3c6f6c3aa1d6?auto=format&fit=crop&w=800&q=80', '클릭 바 구조로 찰칵거리는 청각적 피드백을 제공합니다.', TRUE, FALSE, NULL, 0, NOW(), NOW()),
(41, 'switch-linear', '체리 MX 2A Black 리니어 스위치 60g (90개입)', 48000, 30, 'https://images.unsplash.com/photo-1587829741301-dc798b83add3?auto=format&fit=crop&w=800&q=80', '독일 체리 정품 2A 공정으로 윤활되어 타건감이 극대화된 클래식 흑축 스위치입니다.', TRUE, FALSE, NULL, 0, NOW(), NOW()),
(42, 'switch-linear', '게이트론 오일킹(Oil King) 리니어 55g (90개입)', 59000, 28, 'https://images.unsplash.com/photo-1511467687858-23d96c32e4ae?auto=format&fit=crop&w=800&q=80', '완벽한 공장 윤활과 블랙 하우징에서 뿜어져 나오는 묵직한 조약돌 타건음의 최고봉입니다.', TRUE, FALSE, NULL, 0, NOW(), NOW()),
(45, 'switch-tactile', 'Gazzew Boba U4T Thock 택타일 62g (90개입)', 68000, 18, 'https://images.unsplash.com/photo-1541140532154-b024d705b909?auto=format&fit=crop&w=800&q=80', '두터운 걸림감과 함께 로우피치 도각거림을 완벽하게 동시에 구현한 하이엔드 걸작입니다.', TRUE, FALSE, NULL, 0, NOW(), NOW()),
(46, 'switch-silent', '오테뮤 라임 V3 저소음 넌클릭 택타일 35g (90개입)', 32000, 45, 'https://images.unsplash.com/photo-1618384887929-16ec33fab9ef?auto=format&fit=crop&w=800&q=80', '사무실 장시간 타이핑에도 손목 피로가 없는 가성비 최고의 저소음 택타일 축입니다.', TRUE, FALSE, NULL, 0, NOW(), NOW()),
(47, 'switch-click', '게이트론 멜론 클릭키 스위치 55g (90개입)', 38000, 24, 'https://images.unsplash.com/photo-1601445638532-3c6f6c3aa1d6?auto=format&fit=crop&w=800&q=80', '타자기 특유의 명쾌하고 시원한 클릭 사운드를 구현한 산뜻한 컬러의 스위치입니다.', TRUE, FALSE, NULL, 0, NOW(), NOW()),
(48, 'switch-linear', 'JWK FFFF 리니어 커스텀 스위치 50g (90개입)', 52000, 26, 'https://images.unsplash.com/photo-1587829741301-dc798b83add3?auto=format&fit=crop&w=800&q=80', 'JWK 특유의 흔들림 없는 스템과 부드러운 하향 스트로크가 인상적인 리니어 축입니다.', TRUE, FALSE, NULL, 0, NOW(), NOW()),
(9, 'keycap-pbt', '레트로 9009 PBT 염료승화 키캡', 42000, 30, 'https://images.unsplash.com/photo-1626785774573-4b799315345d?auto=format&fit=crop&w=800&q=80', '두꺼운 1.5mm PBT 원사를 사용하여 번들거림 없이 뽀송한 클래식 레트로 키캡입니다.', TRUE, FALSE, NULL, 0, NOW(), NOW()),
(10, 'keycap-pbt', '보타닉 포레스트 PBT 한영 키캡', 48000, 22, 'https://images.unsplash.com/photo-1601445638532-3c6f6c3aa1d6?auto=format&fit=crop&w=800&q=80', '딥그린과 크림 화이트의 정갈한 컬러 하모니가 돋보이는 PBT 키캡입니다.', TRUE, FALSE, NULL, 0, NOW(), NOW()),
(52, 'keycap-abs', '미드나잇 퍼플 ABS 이중사출 키캡', 56000, 20, 'https://images.unsplash.com/photo-1595225476474-87563907a212?auto=format&fit=crop&w=800&q=80', '깊은 보랏빛과 네온 옐로우 각인의 환상적인 대비를 연출하는 키캡 세트입니다.', TRUE, FALSE, NULL, 0, NOW(), NOW()),
(53, 'keycap-pbt', '밀크 앤 허니 체리프로파일 PBT 승화 키캡', 39000, 28, 'https://images.unsplash.com/photo-1511467687858-23d96c32e4ae?auto=format&fit=crop&w=800&q=80', '따뜻한 우유와 꿀을 연상시키는 포근한 옐로우/화이트 컬러 테마의 PBT 키캡입니다.', TRUE, FALSE, NULL, 0, NOW(), NOW()),
(54, 'keycap-pbt', '쇼코(Shoko) 블루 그레이 PBT 이중사출 키캡', 49000, 22, 'https://images.unsplash.com/photo-1618384887929-16ec33fab9ef?auto=format&fit=crop&w=800&q=80', '청량하고 산뜻한 파스텔 블루와 그레이의 완벽한 밸런스를 보여주는 키캡 세트입니다.', TRUE, FALSE, NULL, 0, NOW(), NOW()),
(55, 'keycap-abs', '오블리비언(Oblivion) Git 테마 ABS 키캡', 62000, 15, 'https://images.unsplash.com/photo-1550745165-9bc0b252726f?auto=format&fit=crop&w=800&q=80', '개발자들의 로망인 코드 에디터 문법 하이라이트 컬러를 담은 ABS 이중사출 키캡입니다.', TRUE, FALSE, NULL, 0, NOW(), NOW()),
(56, 'keycap-pom', '젤리 젤라또 POM 무각 반투명 키캡', 36000, 30, 'https://images.unsplash.com/photo-1541140532154-b024d705b909?auto=format&fit=crop&w=800&q=80', '독특한 POM 재질 특유의 조약돌 마찰음과 은은한 LED 투과력을 자랑하는 키캡입니다.', TRUE, FALSE, NULL, 0, NOW(), NOW()),
(57, 'keycap-pom', '프로스트 화이트 POM 측각 키캡', 38000, 24, 'https://images.unsplash.com/photo-1587829741301-dc798b83add3?auto=format&fit=crop&w=800&q=80', '정면에는 각인이 없어 깔끔하고, 측면 레이저 각인으로 시인성을 확보한 POM 키캡입니다.', TRUE, FALSE, NULL, 0, NOW(), NOW()),
(58, 'keycap-pbt', '클래식 빈티지 매킨토시 PBT 염료승화 키캡', 44000, 19, 'https://images.unsplash.com/photo-1626785774573-4b799315345d?auto=format&fit=crop&w=800&q=80', '1984년 오리지널 매킨토시의 키보드 폰트와 심볼을 정교하게 재현한 레트로 키캡입니다.', TRUE, FALSE, NULL, 0, NOW(), NOW()),
(15, 'housing-pc', '프로스트 75 클리어 PC 하우징', 79000, 15, 'https://images.unsplash.com/photo-1587829741301-dc798b83add3?auto=format&fit=crop&w=800&q=80', '은은한 RGB 조명 투과와 정숙한 타건음을 자랑하는 75배열 PC 하우징입니다.', TRUE, FALSE, NULL, 0, NOW(), NOW()),
(16, 'housing-pc', '스모크 65 반투명 폴리카보네이트 하우징', 69000, 18, 'https://images.unsplash.com/photo-1511467687858-23d96c32e4ae?auto=format&fit=crop&w=800&q=80', '다크 스모키 질감의 고급 폴리카보네이트 소재로 완성한 65배열 하우징입니다.', TRUE, FALSE, NULL, 0, NOW(), NOW()),
(18, 'housing-alu', '알루미늄 하우징 Stealth 65', 112000, 12, 'https://images.unsplash.com/photo-1595225476474-87563907a212?auto=format&fit=crop&w=800&q=80', '매트 블랙 아노다이징 코팅으로 묵직한 존재감을 선사하는 65배열 알루미늄 하우징입니다.', TRUE, FALSE, NULL, 0, NOW(), NOW()),
(19, 'housing-alu', '알루미늄 하우징 Phantom TKL', 135000, 14, 'https://images.unsplash.com/photo-1541140532154-b024d705b909?auto=format&fit=crop&w=800&q=80', '정밀 CNC 가공 베벨 컷팅과 하판 황동 무게추가 적용된 프리미엄 TKL 하우징입니다.', TRUE, FALSE, NULL, 0, NOW(), NOW()),
(61, 'pcb-wireless', '87키 카일 핫스왑 블루투스 듀얼 무선 PCB', 56000, 20, 'https://images.unsplash.com/photo-1587829741301-dc798b83add3?auto=format&fit=crop&w=800&q=80', '블루투스 5.2를 지원하며 정방향 RGB LED가 탑재된 텐키리스 무선 기판입니다.', TRUE, FALSE, NULL, 0, NOW(), NOW()),
(62, 'pcb-solder', '75% 정방향 LED 솔더링 PCB', 38000, 15, 'https://images.unsplash.com/photo-1511467687858-23d96c32e4ae?auto=format&fit=crop&w=800&q=80', '견고한 결착력과 안정적인 전기 신호를 보장하는 75배열 솔더링 기판입니다.', TRUE, FALSE, NULL, 0, NOW(), NOW()),
(63, 'pcb-hotswap', '65% 황동 보강판 일체형 핫스왑 기판', 49000, 16, 'https://images.unsplash.com/photo-1541140532154-b024d705b909?auto=format&fit=crop&w=800&q=80', '황동 소재 특유의 단단하고 깔끔한 타건음을 자랑하는 65% 핫스왑 기판입니다.', TRUE, FALSE, NULL, 0, NOW(), NOW()),
(64, 'kb-75', 'Zoom75 EE 75% 풀알루미늄 무선 베어본', 219000, 8, 'https://images.unsplash.com/photo-1550745165-9bc0b252726f?auto=format&fit=crop&w=800&q=80', 'LCD 디스플레이 모듈과 무선 트라이모드를 모두 지원하는 하이엔드 75% 베어본입니다.', TRUE, FALSE, NULL, 0, NOW(), NOW()),
(65, 'kb-65', 'QK65 V2 클래식 65% 베어본 키트', 189000, 11, 'https://images.unsplash.com/photo-1618384887929-16ec33fab9ef?auto=format&fit=crop&w=800&q=80', '정교한 가스켓 마운트와 두터운 하판 무게추로 쫀득한 타건감을 구현한 베어본입니다.', TRUE, FALSE, NULL, 0, NOW(), NOW()),
(66, 'kb-75', 'QK75N 로터리 노브 75% 베어본', 229000, 9, 'https://images.unsplash.com/photo-1601445638532-3c6f6c3aa1d6?auto=format&fit=crop&w=800&q=80', '미니 스크린과 다기능 노브를 내장하여 데스크 작업성을 극대화한 프리미엄 베어본입니다.', TRUE, FALSE, NULL, 0, NOW(), NOW()),
(67, 'kb-tkl', 'Suit 80 TKL 알루미늄 가스켓 베어본', 289000, 6, 'https://images.unsplash.com/photo-1595225476474-87563907a212?auto=format&fit=crop&w=800&q=80', '완벽한 클래식 타건음과 정교한 기구 설계로 마니아들의 극찬을 받는 최고급 TKL 베어본입니다.', TRUE, FALSE, NULL, 0, NOW(), NOW()),
(71, 'switch-linear', '게이트론 CJ 블루 리니어 스위치 50g (90개입)', 52000, 28, 'https://images.unsplash.com/photo-1587829741301-dc798b83add3?auto=format&fit=crop&w=800&q=80', '극강의 매끄러움과 맑은 하이피치 사운드를 들려주는 블루 하우징의 리니어 스위치입니다.', TRUE, FALSE, NULL, 0, NOW(), NOW()),
(72, 'switch-linear', '아쿠아 킹 V3 투명 리니어 스위치 62g (90개입)', 59000, 24, 'https://images.unsplash.com/photo-1511467687858-23d96c32e4ae?auto=format&fit=crop&w=800&q=80', 'RGB 조명 투과율 100%의 올 클리어 하우징과 두터운 윤활감이 매력적인 스위치입니다.', TRUE, FALSE, NULL, 0, NOW(), NOW()),
(73, 'switch-tactile', '체리 MX 2A Brown 넌클릭 택타일 55g (90개입)', 48000, 32, 'https://images.unsplash.com/photo-1541140532154-b024d705b909?auto=format&fit=crop&w=800&q=80', '체리 최신 2A 공정으로 서걱임을 완전히 잡은 정통 갈축 택타일 스위치입니다.', TRUE, FALSE, NULL, 0, NOW(), NOW()),
(74, 'switch-tactile', 'Bsun Raw 택타일 넌클릭 스위치 60g (90개입)', 55000, 21, 'https://images.unsplash.com/photo-1618384887929-16ec33fab9ef?auto=format&fit=crop&w=800&q=80', '순수 소재 본연의 또렷한 걸림과 쾌활한 바닥 타건음을 제공하는 택타일 축입니다.', TRUE, FALSE, NULL, 0, NOW(), NOW()),
(75, 'switch-silent', '게이트론 저소음 갈축 넌클릭 스위치 45g (90개입)', 44000, 36, 'https://images.unsplash.com/photo-1601445638532-3c6f6c3aa1d6?auto=format&fit=crop&w=800&q=80', '조용한 사무 공간에서 가벼운 구분감과 정숙성을 동시에 누릴 수 있는 저소음 갈축입니다.', TRUE, FALSE, NULL, 0, NOW(), NOW()),
(76, 'switch-click', '카일 제이드 두꺼운 클릭바 스위치 50g (90개입)', 45000, 18, 'https://images.unsplash.com/photo-1595225476474-87563907a212?auto=format&fit=crop&w=800&q=80', '두꺼운 Thick Click Bar를 사용하여 한 번 누르면 잊을 수 없는 쾌감을 선사하는 청축 계열입니다.', TRUE, FALSE, NULL, 0, NOW(), NOW()),
(81, 'keycap-pbt', '화이트 온 블랙(WoB) PBT 이중사출 키캡', 42000, 35, 'https://images.unsplash.com/photo-1587829741301-dc798b83add3?auto=format&fit=crop&w=800&q=80', '어떤 하우징에도 군더더기 없이 어울리는 영원한 베스트셀러 화이트 온 블랙 키캡입니다.', TRUE, FALSE, NULL, 0, NOW(), NOW()),
(82, 'keycap-pbt', '블랙 온 화이트(BoW) PBT 이중사출 키캡', 42000, 30, 'https://images.unsplash.com/photo-1511467687858-23d96c32e4ae?auto=format&fit=crop&w=800&q=80', '순백의 깔끔함과 또렷한 블랙 각인이 돋보이는 모던 미니멀 스타일의 키캡입니다.', TRUE, FALSE, NULL, 0, NOW(), NOW()),
(83, 'keycap-abs', '카멜레온 네온 ABS 이중사출 키캡', 58000, 17, 'https://images.unsplash.com/photo-1541140532154-b024d705b909?auto=format&fit=crop&w=800&q=80', '사이퍼펑크 감성의 비비드한 네온 컬러 팔레트가 적용된 ABS 이중사출 키캡입니다.', TRUE, FALSE, NULL, 0, NOW(), NOW()),
(84, 'keycap-pbt', '세이지 그린 PBT 염료승화 키캡', 46000, 24, 'https://images.unsplash.com/photo-1550745165-9bc0b252726f?auto=format&fit=crop&w=800&q=80', '차분한 허브향이 느껴지는 감성적인 세이지 그린 톤의 PBT 승화 키캡 세트입니다.', TRUE, FALSE, NULL, 0, NOW(), NOW()),
(85, 'keycap-pbt', '레트로 카본 체리프로파일 PBT 승화 키캡', 49000, 20, 'https://images.unsplash.com/photo-1618384887929-16ec33fab9ef?auto=format&fit=crop&w=800&q=80', '진한 카본 그레이와 오렌지 포인트 키캡의 강렬한 조화가 일품인 키캡 세트입니다.', TRUE, FALSE, NULL, 0, NOW(), NOW()),
(86, 'keycap-pom', '프로스트 스모크 POM 반투명 측각 키캡', 39000, 27, 'https://images.unsplash.com/photo-1601445638532-3c6f6c3aa1d6?auto=format&fit=crop&w=800&q=80', '은은한 스모키 반투명 블랙 재질에 정갈한 측면 각인으로 고급스러움을 더했습니다.', TRUE, FALSE, NULL, 0, NOW(), NOW()),
(87, 'keycap-pom', '버블검 핑크 POM 글로시 키캡', 37000, 23, 'https://images.unsplash.com/photo-1626785774573-4b799315345d?auto=format&fit=crop&w=800&q=80', '매끄러운 POM 고유의 질감과 사랑스러운 핑크 컬러가 돋보이는 키캡 세트입니다.', TRUE, FALSE, NULL, 0, NOW(), NOW())
